        controlledByUser: false
    };

    const { api, session } = await bootstrapSession({
        flavor: 'opencode',
        startedBy,
        workingDirectory,
        agentState: initialState
    });

    const startingMode: 'local' | 'remote' = opts.startingMode
        ?? (startedBy === 'runner' ? 'remote' : 'local');

