160	    let host: string | null = null
161	    let port = 443
162	
163	    try {
164	        const parsedUrl = new URL(tunnelUrl)
165	        if (parsedUrl.protocol !== 'https:') {
166	            return true
167	        }
168	        host = parsedUrl.hostname
169	        if (parsedUrl.port) {
170	            const parsedPort = Number.parseInt(parsedUrl.port, 10)
171	            if (Number.isFinite(parsedPort)) {
172	                port = parsedPort
173	            }
174	        }
